import test from 'node:test';
import assert from 'node:assert/strict';
import {E_CHARGE} from '../src/physics.js';
import {DEFAULT_FUSION_BEAM,dtCrossSectionM2,simulateFusionBeam} from '../src/fusion-reactor.js';

test('DT cross sections reproduce independently published millibarn table and reject extrapolation',()=>{
 // MIT MFE Formulary §9.7, rounded Bosch–Hale table; not generated by this module.
 for(const [energyCM,millibarn] of [[3,.009808],[5,.5383],[10,27.02],[20,407.7]])
  assert.ok(Math.abs(dtCrossSectionM2(energyCM)/1e-31/millibarn-1)<3e-4);
 for(const e of [-1,0,.49,551,NaN,Infinity])assert.throws(()=>dtCrossSectionM2(e),/0.5–550/);
});

test('monoenergetic no-stopping slab reproduces exact attenuation and dimensional neutron/current/Q identities',()=>{
 const c={...DEFAULT_FUSION_BEAM,stoppingFraction:0,targetColumnM2:1e25};
 const r=simulateFusionBeam(c),tau=c.targetColumnM2*dtCrossSectionM2(.6*c.beamEnergyKeV);
 assert.ok(Math.abs(r.fusionProbability-(-Math.expm1(-tau)))<1e-14);
 assert.ok(Math.abs(r.transmittedFraction-Math.exp(-tau))<1e-14);
 assert.equal(r.beamPowerW,c.beamCurrentA*c.beamEnergyKeV*1000);
 assert.ok(Math.abs(r.neutronRateS/(r.fusionProbability*c.beamCurrentA/E_CHARGE)-1)<1e-14);
 assert.ok(Math.abs(r.nuclearPowerW/(r.neutronRateS*17.6e6*E_CHARGE)-1)<1e-14);
 assert.ok(Math.abs(r.relativeEnergyResidual!)<1e-14);
 assert.equal(r.assemblyHeatIfTransmittedBeamStoppedW,r.targetLayerHeatW+r.transmittedBeamPowerW);
});

test('slowing slab conserves number/energy with independent product deposition and resolves under quadrature refinement',()=>{
 const runs=[100,200,400,800].map(intervals=>simulateFusionBeam({...DEFAULT_FUSION_BEAM,
  beamEnergyKeV:300,stoppingFraction:.9,targetColumnM2:1e25,alphaDepositedFraction:.3,intervals}));
 for(const r of runs){
  assert.ok(Math.abs(r.fusionProbability+r.transmittedFraction-1)<1e-13);
  assert.ok(Math.abs(r.relativeEnergyResidual!)<1e-13);
  assert.ok(r.transmittedBeamPowerW>0&&r.beamStoppingPowerW>0&&r.escapingAlphaPowerW>0);
  assert.ok(r.profiles.every((p,i,a)=>i===0||p.fusionProbability>=a[i-1].fusionProbability));
 }
 const differences=runs.slice(1).map((r,i)=>Math.abs(r.fusionProbability-runs[i].fusionProbability));
 assert.ok(differences[1]<differences[0]/3);assert.ok(differences[2]<differences[1]/3);
});

test('zero tritium and zero current limits retain a clear beam heat ledger without fictitious fusion',()=>{
 const noT=simulateFusionBeam({...DEFAULT_FUSION_BEAM,targetColumnM2:0});
 assert.equal(noT.neutronRateS,0);assert.equal(noT.nuclearPowerW,0);
 assert.ok(Math.abs(noT.beamStoppingPowerW-noT.beamPowerW*.2)<1e-10);
 assert.ok(Math.abs(noT.relativeEnergyResidual!)<1e-13);
 const off=simulateFusionBeam({...DEFAULT_FUSION_BEAM,beamCurrentA:0});
 assert.equal(off.neutronRateS,0);assert.equal(off.targetLayerHeatW,0);assert.equal(off.beamGain,null);
 assert.equal(off.relativeEnergyResidual,null);
 assert.throws(()=>simulateFusionBeam({...DEFAULT_FUSION_BEAM,beamEnergyKeV:1,stoppingFraction:.9}),/0.5–550/);
 assert.throws(()=>simulateFusionBeam({...DEFAULT_FUSION_BEAM,alphaDepositedFraction:2}));
});

test('finite API inputs producing unrepresentable rates, exposure counts or heat flux fail explicitly',()=>{
 for(const extreme of [{beamCurrentA:1e300},{beamAreaM2:1e-320},{exposureS:1e308}])
  assert.throws(()=>simulateFusionBeam({...DEFAULT_FUSION_BEAM,...extreme}),/representable finite numeric domain/);
});
